PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),owner TEXT NOT NULL,name TEXT NOT NULL DEFAULT 'Mi organización',timezone TEXT NOT NULL DEFAULT 'America/La_Paz');
CREATE TABLE IF NOT EXISTS members(email TEXT PRIMARY KEY,user_id TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','operator','viewer')),active INTEGER NOT NULL DEFAULT 1,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES members(user_id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS zones(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',capacity INTEGER NOT NULL DEFAULT 0 CHECK(capacity>=0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,name TEXT NOT NULL,days TEXT NOT NULL,start TEXT NOT NULL,end TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS people(id TEXT PRIMARY KEY,name TEXT NOT NULL,document TEXT UNIQUE NOT NULL,email TEXT NOT NULL DEFAULT '',department TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL DEFAULT 'employee',status TEXT NOT NULL DEFAULT 'active',expires TEXT,schedule_id TEXT REFERENCES schedules(id),notes TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS person_zones(person_id TEXT NOT NULL REFERENCES people(id),zone_id TEXT NOT NULL REFERENCES zones(id),PRIMARY KEY(person_id,zone_id));
CREATE TABLE IF NOT EXISTS credentials(id TEXT PRIMARY KEY,person_id TEXT NOT NULL REFERENCES people(id),kind TEXT NOT NULL,label TEXT NOT NULL,hash TEXT UNIQUE NOT NULL,suffix TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS credentials_person ON credentials(person_id);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,name TEXT NOT NULL,zone_id TEXT NOT NULL REFERENCES zones(id),kind TEXT NOT NULL,direction TEXT NOT NULL,hash TEXT UNIQUE NOT NULL,active INTEGER NOT NULL DEFAULT 1,last_seen INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,request_key TEXT UNIQUE NOT NULL,payload_hash TEXT NOT NULL,person_id TEXT REFERENCES people(id),person_name TEXT NOT NULL,zone_id TEXT NOT NULL REFERENCES zones(id),zone_name TEXT NOT NULL,direction TEXT NOT NULL,method TEXT NOT NULL,allowed INTEGER NOT NULL,reason TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',actor TEXT NOT NULL,device_id TEXT REFERENCES devices(id),occurred_at INTEGER NOT NULL,local_date TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_presence ON events(person_id,zone_id,allowed,id);
CREATE INDEX IF NOT EXISTS events_date ON events(local_date);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,occurred_at INTEGER NOT NULL);
INSERT OR IGNORE INTO schema_version(version) VALUES(1);
